# The Book of Armaments, Chapter Two: Testing the Holy Checkout

*Consult ye the sacred texts...*

And the Lord did grin, and the people did feast upon the lambs, and sloths, and carp, and... Right. Skip a bit. The important part is:

```typescript
// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// And the mocks shall be thus:
const mockCart = {
  items: [{ id: '1', name: 'Holy Grail', price: 999.99 }],
  total: 999.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({ useCart: () => mockCart }));
vi.mock('./PaymentContext', () => ({ usePayment: () => mockPayment }));

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Holy Grail', price: 999.99 }];
  });

  // ONE: The Happy Path
  describe('Complete Checkout Flow', () => {
    it('completes checkout: One, two, FIVE— three, sir! Three steps!', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });

      render(<Checkout onComplete={onComplete} />);

      // Step ONE: Shipping
      await user.type(screen.getByLabelText(/street address/i), '123 Camelot Lane');
      await user.type(screen.getByLabelText(/city/i), 'Camelot');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Step TWO: Payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Sir Galahad');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Step THREE: Review and Place Order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // TWO: Validation Errors
  describe('Form Validation', () => {
    it('shows error when ZIP is invalid', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'AAAAA');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // THREE: Empty Cart
  describe('Edge Cases', () => {
    it('displays empty cart message when cart has no items', () => {
      mockCart.items = [];
      render(<Checkout />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  // FOUR: Accessibility
  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });

  // FIVE: Error Recovery
  describe('Payment Errors', () => {
    it('displays payment error and allows retry', async () => {
      const user = userEvent.setup();
      mockPayment.processPayment.mockRejectedValueOnce(new Error('Insufficient funds'));

      // ... navigate to review step, then:
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/insufficient funds/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });
});
